script:
(function () {
  'use strict';
  // Marriage tax: 2026 federal tax for two people filing as unmarried (single or head of household)
  // versus married filing jointly and married filing separately.
  //   AGI            = wages + other ordinary income - pre-tax retirement/HSA contributions
  //   Taxable income = AGI - larger of standard (+ 65+ additional) or itemized - senior deduction
  //   Income tax     = progressive brackets - child tax credit (limited to the tax, phased out
  //                    $50 per $1,000 or part over the threshold)
  //   + 0.9% Additional Medicare tax on wages over $200,000 (single/HOH), $250,000 (joint, combined
  //     wages) or $125,000 (separate)
  //   Married filing separately: if either spouse itemizes, both must itemize; no senior deduction.
  // Not modeled: refundable child credit, earned income credit, capital gains rates, SALT cap,
  //   self-employment tax, state tax.
  // Verified (Node, scratch tests, against hand calculations from the Rev. Proc. 2025-32 tables):
  //   $75,000 + $45,000 wages, no other inputs -> single $7,670.00 + $3,220.00 = $10,890.00;
  //     joint taxable $87,800 -> $2,480 + 12% x $63,000 = $10,040.00 (marriage bonus $850.00).
  //   $400,000 + $400,000 wages -> income tax identical ($206,268.50) single or joint, but Additional
  //     Medicare $1,800 x 2 = $3,600 single vs 0.9% x $550,000 = $4,950 joint (penalty $1,350.00).
  //   $120,000 + $0, single + HOH, 2 children with partner 2 -> joint credit $4,400.
  //   Same constants as take-home-paycheck-calculator / income-tax-calculator (checked against the
  //   Rev. Proc. 2025-32 text). Whole script run under Node with a stub DOM: no NaN/Infinity.
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets and standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21), s. 4.01.
  // Additional standard deduction (65+), child tax credit ($2,200), senior deduction ($6,000,
  //   6% phase-out over $75,000 / $150,000 joint, 2025-2028, not for married filing separately):
  //   IRC 63(f), 24(h) and 151(d)(5)(C) as amended by P.L. 119-21; Rev. Proc. 2025-32.
  // Additional Medicare tax 0.9% and thresholds: IRC 3101(b)(2) (statutory, not indexed).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var ADDITIONAL_65 = { single: 2050, hoh: 2050, mfj: 1650, mfs: 1650 }; // per person 65+
  var SENIOR_DEDUCTION = 6000, SENIOR_PHASEOUT_RATE = 0.06;
  var SENIOR_PHASEOUT_START = { single: 75000, hoh: 75000, mfj: 150000 };
  var CHILD_CREDIT = 2200; // per child under 17
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 };
  var ADDL_MEDICARE_RATE = 0.009;
  var ADDL_MEDICARE_START = { single: 200000, hoh: 200000, mfj: 250000, mfs: 125000 };
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = RATES[0];
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) {
        tax += (Math.min(taxable, upper) - lower) * RATES[i];
        marginal = RATES[i];
      }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // One return. p: { status, wages, other, pretax, itemized, kids, seniors, mustItemize }
  function taxReturn(p) {
    var s = p.status;
    var agi = Math.max(0, p.wages + p.other - p.pretax);
    var standard = STANDARD_DEDUCTION[s] + p.seniors * ADDITIONAL_65[s];
    var itemize = p.mustItemize || p.itemized > standard;
    var deduction = itemize ? p.itemized : standard;
    var senior = 0;
    if (s !== 'mfs' && p.seniors > 0) {
      senior = p.seniors * Math.max(0, SENIOR_DEDUCTION - SENIOR_PHASEOUT_RATE * Math.max(0, agi - SENIOR_PHASEOUT_START[s]));
    }
    var taxable = Math.max(0, agi - deduction - senior);
    var bt = bracketTax(taxable, BRACKETS[s]);
    var credit = p.kids * CHILD_CREDIT;
    credit = Math.max(0, credit - Math.ceil(Math.max(0, agi - CREDIT_PHASEOUT_START[s]) / 1000) * 50);
    var creditUsed = Math.min(credit, bt.tax);
    var addl = ADDL_MEDICARE_RATE * Math.max(0, p.wages - ADDL_MEDICARE_START[s]);
    var total = bt.tax - creditUsed + addl;
    return {
      status: s, agi: agi, deduction: deduction + senior, itemize: itemize, taxable: taxable,
      incomeTax: bt.tax, credit: creditUsed, addl: addl, total: total, marginal: bt.marginal,
      effective: p.wages + p.other > 0 ? total / (p.wages + p.other) : 0
    };
  }

  function compare(a, b) {
    var singleA = taxReturn({ status: a.status, wages: a.wages, other: a.other, pretax: a.pretax, itemized: a.itemized,
      kids: a.kids, seniors: a.senior ? 1 : 0, mustItemize: false });
    var singleB = taxReturn({ status: b.status, wages: b.wages, other: b.other, pretax: b.pretax, itemized: b.itemized,
      kids: b.kids, seniors: b.senior ? 1 : 0, mustItemize: false });
    var joint = taxReturn({ status: 'mfj', wages: a.wages + b.wages, other: a.other + b.other, pretax: a.pretax + b.pretax,
      itemized: a.itemized + b.itemized, kids: a.kids + b.kids, seniors: (a.senior ? 1 : 0) + (b.senior ? 1 : 0),
      mustItemize: false });
    // Separate returns: if either spouse would itemize, both have to.
    var stdA = STANDARD_DEDUCTION.mfs + (a.senior ? ADDITIONAL_65.mfs : 0);
    var stdB = STANDARD_DEDUCTION.mfs + (b.senior ? ADDITIONAL_65.mfs : 0);
    var must = a.itemized > stdA || b.itemized > stdB;
    var sepA = taxReturn({ status: 'mfs', wages: a.wages, other: a.other, pretax: a.pretax, itemized: a.itemized,
      kids: a.kids, seniors: a.senior ? 1 : 0, mustItemize: must });
    var sepB = taxReturn({ status: 'mfs', wages: b.wages, other: b.other, pretax: b.pretax, itemized: b.itemized,
      kids: b.kids, seniors: b.senior ? 1 : 0, mustItemize: must });
    return {
      singleA: singleA, singleB: singleB, joint: joint, sepA: sepA, sepB: sepB, mustItemize: must,
      unmarried: singleA.total + singleB.total, separate: sepA.total + sepB.total
    };
  }

  // ---- page wiring ----------------------------------------------------------------------
  function readNum(id) {
    var el = document.getElementById(id);
    if (!el || el.value === '') return 0;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }
  function isChecked(id) { var el = document.getElementById(id); return !!(el && el.checked); }
  function selectVal(id, allowed, fallback) {
    var el = document.getElementById(id);
    return el && allowed.indexOf(el.value) !== -1 ? el.value : fallback;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function pct(v) { return (v * 100).toFixed(1) + '%'; }

  function person(suffix) {
    return {
      wages: readNum('mtWages' + suffix), other: readNum('mtOther' + suffix), pretax: readNum('mtPretax' + suffix),
      itemized: readNum('mtItemized' + suffix), kids: readNum('mtKids' + suffix),
      status: selectVal('mtStatus' + suffix, ['single', 'hoh'], 'single'), senior: isChecked('mtSenior' + suffix)
    };
  }

  function fillTable(rows) {
    var body = document.getElementById('mtTable');
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (t, i) {
        var td = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) td.setAttribute('scope', 'row');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  function clear() {
    ['mtResult', 'mtUnmarried', 'mtJoint', 'mtSeparate'].forEach(function (id) { set(id, '–'); });
    set('mtResultLabel', 'Marriage penalty or bonus');
    set('mtSummary', '');
    fillTable([]);
    var note = document.getElementById('mtNote');
    if (note) note.hidden = true;
  }

  function update() {
    var a = person('A'), b = person('B');
    var values = [a.wages, a.other, a.pretax, a.itemized, a.kids, b.wages, b.other, b.pretax, b.itemized, b.kids];
    var msg = '';
    if (values.some(function (v) { return !isFinite(v) || Math.abs(v) > 1e10; })) msg = 'Enter numbers only. Leave a field at 0 if it does not apply.';
    else if (values.some(function (v) { return v < 0; })) msg = 'Enter amounts of 0 or more.';
    else if ([a.kids, b.kids].some(function (k) { return k > 20 || Math.round(k) !== k; })) msg = 'Enter the number of children as a whole number up to 20.';
    var error = document.getElementById('mtError');
    if (error) { error.hidden = !msg; error.textContent = msg; }
    if (msg) { clear(); return; }

    var r = compare(a, b);
    var diff = r.joint.total - r.unmarried;
    if (Math.abs(diff) < 0.005) {
      set('mtResultLabel', 'No marriage penalty or bonus');
      set('mtResult', money.format(0));
      set('mtSummary', 'Filing jointly costs the same as filing as two unmarried people.');
    } else if (diff > 0) {
      set('mtResultLabel', 'Marriage penalty');
      set('mtResult', money.format(diff));
      set('mtSummary', 'Filing jointly costs ' + money.format(diff) + ' more a year than filing as two unmarried people.');
    } else {
      set('mtResultLabel', 'Marriage bonus');
      set('mtResult', money.format(-diff));
      set('mtSummary', 'Filing jointly saves ' + money.format(-diff) + ' a year compared with filing as two unmarried people.');
    }
    set('mtUnmarried', money.format(r.unmarried));
    set('mtJoint', money.format(r.joint.total));
    set('mtSeparate', money.format(r.separate));

    var cols = [r.singleA, r.singleB, r.joint, r.sepA, r.sepB];
    function row(label, f) { return [label].concat(cols.map(f)); }
    fillTable([
      row('Filing status', function (c) {
        return { single: 'Single', hoh: 'Head of household', mfj: 'Married, jointly', mfs: 'Married, separately' }[c.status];
      }),
      row('Adjusted gross income', function (c) { return money.format(c.agi); }),
      row('Deduction', function (c) { return (c.itemize ? 'Itemized ' : 'Standard ') + money.format(c.deduction); }),
      row('Taxable income', function (c) { return money.format(c.taxable); }),
      row('Income tax before credits', function (c) { return money.format(c.incomeTax); }),
      row('Child tax credit', function (c) { return c.credit > 0 ? '−' + money.format(c.credit) : money.format(0); }),
      row('Additional Medicare tax', function (c) { return money.format(c.addl); }),
      row('Total federal tax', function (c) { return money.format(c.total); }),
      row('Top bracket', function (c) { return Math.round(c.marginal * 100) + '%'; }),
      row('Effective rate', function (c) { return pct(c.effective); })
    ]);

    var notes = [];
    if (r.separate < r.joint.total - 0.005) notes.push('Filing separately comes out ' + money.format(r.joint.total - r.separate) + ' lower than filing jointly here, but it also rules out several credits and deductions this estimate does not include.');
    if (r.mustItemize) notes.push('One of you itemizes, so on separate returns both spouses must itemize.');
    if ((a.status === 'hoh' && a.kids === 0) || (b.status === 'hoh' && b.kids === 0)) notes.push('Head of household needs a qualifying child or relative who lives with you.');
    if (a.senior || b.senior) notes.push('The $6,000 senior deduction is not available on separate returns.');
    var note = document.getElementById('mtNote');
    if (note) { note.hidden = notes.length === 0; note.textContent = notes.join(' '); }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('mtForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
